// The HAND REVIEW behind docs/coverage-matrix.json (plan item B11): for every item of
// docs/predbat-predheat-requirements.md, where the database design keeps it, or why it is not data.
// scripts/build-coverage-matrix.js proposes targets automatically; each entry here was decided by
// reading the catalogue row (its item, origin, Dir and PD columns) against the schema as built, and the
// matrix records which automatic proposals were rejected. Edit this file, then run
//   node scripts/build-coverage-matrix.js && npm test
//
// Target shorthand (parseTarget):
//   col:table.column        a column of a table or view (PRAGMA table_info)
//   col:table.column#key    a documented key of a JSON column (listed under "JSON keys of" in docs/database.md)
//   attr:key  set:key  kind:x    a row of attribute_def, setting_def, device_kind
//   met:code  src:code      a metric (facts are series of it) and a source
//   act:kind.action         a device_action row
//   fn:name                 an export of src/core/planner-read.js (the planner read layer, plan item B10)
//   view:name               a view

export const DEFINITION = 'An item is COVERED when every piece of data it names has a home in the database as built (a fresh database: '
  + 'schema.sql, every delta, every seed): a table column (or a documented key of a JSON column), a registry row (attribute_def, '
  + 'setting_def, device_kind), a metric for its facts (and a source where the item is a feed), a device_action, a view, or a function '
  + 'of the planner read layer (src/core/planner-read.js) that derives it from stored facts. test/coverage-matrix.test.js checks that '
  + 'every target exists. Home Assistant wiring, presentation, fixed code rules and archived keys are EXCLUDED_NOT_DATA with a reason '
  + '(catalogue section 5 and the Dir "rule" rows). Secret values are kept out of the database by design; the connection row that '
  + 'records them is the target. 100 % = every verified Predbat and PredHeat item that is data is covered: covered / (items - excluded), '
  + 'with the unverified items (PB-DIAG-04 and the 11 planning-design fields of Appendix A) counted apart.';

const KINDS = { col: 'table_column', attr: 'registry_key', set: 'registry_key', kind: 'registry_key', met: 'metric', src: 'source', act: 'device_action', fn: 'read_function', view: 'view' };
export function parseTarget(s) {
  const i = s.indexOf(':');
  const ns = s.slice(0, i);
  const rest = s.slice(i + 1);
  if (!KINDS[ns]) throw new Error(`unknown target shorthand ${s}`);
  switch (ns) {
    case 'col': { const [ref, key] = rest.split('#'); return key ? { kind: 'table_column', ref, json_key: key } : { kind: 'table_column', ref }; }
    case 'attr': return { kind: 'registry_key', ref: `attribute_def:${rest}` };
    case 'set': return { kind: 'registry_key', ref: `setting_def:${rest}` };
    case 'kind': return { kind: 'registry_key', ref: `device_kind:${rest}` };
    case 'met': return { kind: 'metric', ref: `metric:${rest}` };
    case 'src': return { kind: 'source', ref: `source:${rest}` };
    case 'act': return { kind: 'device_action', ref: `device_action:${rest}` };
    case 'fn': return { kind: 'read_function', ref: `planner-read.${rest}` };
    default: return { kind: 'view', ref: `view:${rest}` };
  }
}

const c = (targets, note) => ({ status: 'covered', targets, ...(note ? { note } : {}) });
const x = (reason, note) => ({ status: 'excluded_not_data', reason, ...(note ? { note } : {}) });
const pd = (dir, entry) => ({ ...entry, dir });

