const RULE = 'a fixed rule of the code (catalogue Dir "rule"): code constants, not stored data.';
const ARCHIVED = 'archived only (catalogue status "verified (archived)"): a key of the standalone PredHeat repo (archived 12 Oct 2024) that the integrated PredHeat no longer reads.';
